'use strict';
const CLASSIC_TABS=[['combat','melee','Combat options'],['skills','skills','Skills'],['quests','quests','Quest list'],['bag','bag','Inventory'],['gear','gear','Worn equipment'],['worship','shrine','Worship'],['spells','spells','Magic'],['friends','friends','Friends list'],['ignore','ignore','Ignore list'],['account','exit','Logout'],['settings','tools','Settings'],['emotes','wave','Emotes'],['music','sound','Music'],['tools','mine','Tool belt']];
const classicStorage=document.createElement('div');classicStorage.id='uiStorage';classicStorage.hidden=true;document.body.appendChild(classicStorage);
const classicDockRender=renderPanel,classicSyncTabs=syncTabs,classicOpenSocial=openSocial,classicOpenPanel=openGamePanel;
const classicMobile=()=>window.matchMedia('(pointer: coarse)').matches||window.matchMedia('(max-width: 760px)').matches;
function classicButton(label,action,icon){const b=document.createElement('button');b.type='button';if(icon)b.innerHTML=gameIcon(icon);const text=document.createElement('span');text.textContent=label;b.appendChild(text);b.onclick=action;return b;}
function classicHeading(text){const h=document.createElement('h3');h.className='classic-panel-title';h.textContent=text;$('panel').appendChild(h);return h;}
function parkClassicControls(){for(const id of ['combatbar','friendsPane','fullscreenButton','ambientButton','waveButton','journal','tutorial']){const el=$(id);if(el&&el.parentElement!==classicStorage)classicStorage.appendChild(el);}}
function updateClassicLayout(){document.body.classList.toggle('classic-mobile',classicMobile());document.body.classList.toggle('classic-desktop',!classicMobile());if(typeof resize==='function')resize();}
function updateClassicVitals(){const hp=$('hitpointValue');if(!hp)return;hp.textContent=s.hp;$('hitpointOrb').style.setProperty('--orb-fill',(s.hp/maxhp()*100)+'%');$('hitpointOrb').setAttribute('aria-label','Hitpoints '+s.hp+' of '+maxhp());const ready=Object.values(s.spirits||{}).filter(p=>p.state==='set').length,owned=Object.keys(s.spirits||{}).length;$('worshipValue').textContent=lv('Worship');$('worshipOrb').setAttribute('aria-label','Worship level '+lv('Worship'));$('specialValue').textContent=ready;$('specialOrb').setAttribute('aria-label',ready+' of '+owned+' spirits active. Open special attacks.');$('specialOrb').style.setProperty('--orb-fill',(owned?100*ready/owned:0)+'%');}
function renderClassicCombat(){const p=$('panel'),weapon=equippedWeapon();classicHeading(weapon.name);const level=document.createElement('p');level.className='classic-combat-level';level.textContent='Combat level: '+combatLevel();p.appendChild(level);renderCombatBar();const options=document.createElement('div');options.className='classic-combat-options';for(const option of $('trainingFocus').options){const value=option.value,label=option.textContent.split(' · ')[0],b=classicButton(label,()=>{s[combatStyle()==='melee'?'meleeTraining':combatStyle()+'Training']=value;save();renderClassicPanel();},value==='defensive'?'shield':combatStyle()==='ranged'?'ranged':combatStyle()==='magic'?'magic':'melee');b.setAttribute('aria-pressed',String(value===trainingFocus(combatStyle())));b.title=option.textContent;options.appendChild(b);}p.appendChild(options);const resource=document.createElement('p');resource.className='classic-combat-level';resource.textContent=$('combatResource').textContent;p.appendChild(resource);p.appendChild(classicButton('Special attacks',openSpirits,'spirit'));p.appendChild(classicButton('Change equipment',()=>openGamePanel('bag')));}
function renderClassicFriends(ignore=false){const p=$('panel');classicHeading(ignore?'Ignore list':'Friends list');p.appendChild($('friendsPane'));$('friendsPane').hidden=false;renderFriends();$('friendsList').hidden=ignore;$('ignoreList').hidden=!ignore;$('friendForm').querySelector('button[type=submit],button:not([type])').hidden=ignore;$('ignorePlayer').hidden=!ignore;}
function renderClassicWorship(){classicHeading('Worship: '+lv('Worship'));const grid=document.createElement('div');grid.className='classic-spirit-grid';for(const [id,def]of Object.entries(SPIRITS)){const owned=s.spirits?.[id],b=classicButton(def.name,()=>{selectedSpirit=id;openSpirits();},'spirit');b.style.setProperty('--spirit-color',def.color);b.disabled=!owned;b.title=owned?def.bonus+' '+def.ability:def.hint;b.classList.toggle('active',owned?.state==='set');grid.appendChild(b);}const p=document.createElement('p');p.className='desc';p.textContent='Select a bonded spirit to activate it, put it on standby, or unleash its special attack.';$('panel').append(grid,p);}
function renderClassicSettings(){const p=$('panel');classicHeading('Settings');for(const id of ['fullscreenButton','ambientButton','journal']){const b=$(id);for(const label of b.querySelectorAll('.classic-control-label'))label.remove();p.appendChild(b);b.classList.add('classic-setting-button');}p.appendChild(classicButton('Sound volumes',openSoundSettings,'sound'));p.appendChild(classicButton('Edit appearance',()=>openCreator(true),'gear'));p.appendChild(classicButton('Reset camera',()=>{$('cameraReset').click();},'compass'));}
function renderClassicMusic(){const p=$('panel');classicHeading('Music');p.appendChild(classicButton('Sound & music volumes',openSoundSettings,'sound'));const current=document.createElement('p');current.className='desc';current.textContent='Now playing: '+(gameAudio.current?AREA_MUSIC[gameAudio.current].title:'None');p.appendChild(current);for(const [key,track]of Object.entries(AREA_MUSIC)){const line=document.createElement('p');line.className='classic-music-track';line.textContent=track.title;line.classList.toggle('current',key===gameAudio.current);p.appendChild(line);}}
function renderClassicSpells(){pageControls(1,1);const p=$('panel');p.replaceChildren();classicHeading('Magic: '+lv('Magic'));const grid=document.createElement('div');grid.className='classic-spell-grid';const detail=document.createElement('div');detail.className='classic-spell-detail';detail.setAttribute('role','status');detail.textContent='Select a spell to autocast.';for(const [id,spell]of Object.entries(SPELLS)){const b=document.createElement('button');b.type='button';b.className='classic-spell';b.innerHTML=gameIcon('magic');b.style.setProperty('--spell-color',spell.color);b.title=spell.name+' · Magic '+spell.level;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(s.spell===id));b.classList.toggle('spell-locked',lv('Magic')<spell.level);const describe=()=>{detail.textContent=spell.name+' — Level '+spell.level+'. '+spell.desc+' '+Object.entries(spell.ingredients).map(([id,n])=>n+' '+ITEMS[id].name).join(', ')+'.';};b.onpointerenter=describe;b.onfocus=describe;b.onclick=()=>{describe();if(lv('Magic')<spell.level){toast('You need Magic '+spell.level+' to cast '+spell.name+'.');return;}s.spell=id;if(combatStyle()!=='magic')equipItem('oakStaff');toast(spell.name+' selected for autocasting.');save();renderClassicSpells();};grid.appendChild(b);}p.append(grid,detail);}
function renderClassicPanel(){parkClassicControls();if(tab==='spells')return renderClassicSpells();const custom=['combat','friends','ignore','settings','emotes','music','account','tools','worship'].includes(tab);if(!custom){classicDockRender();if(tab==='quests'){const p=$('panel');const extras=document.createElement('div');extras.className='classic-quest-links';extras.appendChild(classicButton('Hunting journal',()=>openGamePanel('hunts'),'melee'));if(tutorialStep())extras.appendChild(classicButton('Tutorial: '+tutorialStep().title,guide,'tutor'));p.prepend(extras);}return;}
 pageControls(1,1);$('panel').replaceChildren();if(tab==='combat')return renderClassicCombat();if(tab==='friends'||tab==='ignore')return renderClassicFriends(tab==='ignore');if(tab==='worship')return renderClassicWorship();if(tab==='settings')return renderClassicSettings();if(tab==='music')return renderClassicMusic();if(tab==='tools'){toolBeltOpen=true;renderToolBelt();return;}if(tab==='emotes'){classicHeading('Emotes');$('panel').appendChild($('waveButton'));$('waveButton').classList.add('classic-emote');$('waveButton').title='Wave';return;}if(tab==='account'){classicHeading(accountUsername||'Account');const p=document.createElement('p');p.className='desc';p.textContent='Click below to log out safely.';$('panel').append(p,classicButton('Click here to logout',logoutGame,'exit'));}}
renderPanel=renderClassicPanel;
syncTabs=function(){classicSyncTabs();const title=CLASSIC_TABS.find(t=>t[0]===tab)?.[2];if(title)$('dockTitle').textContent=title;document.body.dataset.panel=tab;};
openGamePanel=function(which,toggle=false){if(which!=='tools')toolBeltOpen=false;if(!classicMobile()&&toggle&&tab===which&&!$('gameDock').hidden&&!window.equipmentStatsOpen)toggle=false;return classicOpenPanel(which,toggle);};
openSocial=function(friends=false){if(friends){openGamePanel('friends');return;}socialRoot.hidden=false;socialUnread=0;chatToggle.classList.remove('unread');$('chatPane').hidden=false;};
function installClassicUi(){document.body.classList.add('classic-ui');parkClassicControls();const tabs=$('gameTabs');tabs.replaceChildren();for(const [id,icon,title]of CLASSIC_TABS){const b=document.createElement('button');b.type='button';b.dataset.tab=id;setHudButton(b,title,icon);b.setAttribute('aria-controls','gameDock');b.onclick=()=>openGamePanel(id,true);tabs.appendChild(b);}const map=$('mapHud');map.appendChild($('runButton'));map.appendChild($('spiritButton'));for(const [id,icon,action]of [['hitpoint','heart',()=>openGamePanel('skills')],['worship','shrine',()=>openGamePanel('worship')],['special','melee',openSpirits]]){const b=document.createElement('button');b.id=id+'Orb';b.type='button';b.className='status-orb';b.innerHTML='<span class="orb-icon">'+gameIcon(icon)+'</span><b id="'+id+'Value"></b>';b.onclick=action;map.appendChild(b);}
 $('spiritButton').onclick=openSpirits;setHudButton('spiritButton','Elemental spirits','followers');socialRoot.setAttribute('aria-label','Game chat');chatToggle.title='Show or hide chat';updateClassicLayout();window.addEventListener('resize',updateClassicLayout);window.visualViewport?.addEventListener('resize',updateClassicLayout);flushGameMessages();}
const classicInitHud=initHud;initHud=function(){classicInitHud();updateClassicLayout();if(!classicMobile())openGamePanel('bag');updateClassicVitals();};
installClassicUi();
